<?php
defined('ABSPATH') || exit;
final class TNet_Community_Topic_Composer_Controller {
    private const COMMUNITIES=['community:local-demo'=>'Local Community Demo']; private const MODES=['discussion'=>'Discussion','question'=>'Question','candle'=>'Candle (coming soon)','idea'=>'Idea (coming soon)'];
    public static function register():void{if(!self::local())return;add_rewrite_rule('^community/new/?$','index.php?tnet_community_topic_composer=1','top');add_filter('query_vars',static function(array $v):array{$v[]='tnet_community_topic_composer';return $v;});add_action('template_redirect',[self::class,'render']);}
    private static function local():bool{return defined('DDEV_PROJECT')||(bool)getenv('DDEV_PROJECT');}
    public static function render():void{if(!get_query_var('tnet_community_topic_composer'))return;if(!is_user_logged_in()||!current_user_can('read'))auth_redirect();if('POST'===strtoupper($_SERVER['REQUEST_METHOD']??''))self::submit();self::form([]);exit;}
    private static function urls(string $body):array{preg_match_all('~https://[^\s<>"\']+~i',$body,$m);$out=[];foreach($m[0]??[] as $url){$url=rtrim($url,".,!?;:)");if(!in_array($url,$out,true))$out[]=$url;}return $out;}
    private static function upload():?array{if(empty($_FILES['image_file']['tmp_name']))return null;$f=$_FILES['image_file'];if((int)$f['error']!==UPLOAD_ERR_OK)throw new RuntimeException('IMAGE_UPLOAD_FAILED');if((int)$f['size']>10*1024*1024)throw new RuntimeException('IMAGE_TOO_LARGE');$check=wp_check_filetype_and_ext($f['tmp_name'],$f['name']);if(!in_array($check['type']??'', ['image/jpeg','image/png','image/webp'],true))throw new RuntimeException('IMAGE_TYPE_UNSUPPORTED');if(!empty($check['proper_filename']))$f['name']=$check['proper_filename'];require_once ABSPATH.'wp-admin/includes/file.php';$result=wp_handle_upload($f,['test_form'=>false,'mimes'=>['jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp']]);if(isset($result['error']))throw new RuntimeException('IMAGE_UPLOAD_FAILED');$relative=str_replace(wp_upload_dir()['basedir'].'/','',$result['file']);$mime=$result['type'];return ['attachment_id'=>'upload:'.substr(hash('sha256',$relative),0,16),'attachment_type'=>'image','source_kind'=>'local_upload','source_reference'=>'wp-content/uploads/'.$relative,'title'=>sanitize_file_name($f['name']),'description'=>'Locally staged Community image.','alt_text'=>sanitize_text_field(wp_unslash($_POST['attachment_alt']??'')),'mime_type'=>$mime,'file_size'=>(int)$f['size'],'width'=>null,'height'=>null,'duration_seconds'=>null,'thumbnail_reference'=>null,'rights_status'=>'author_declared','moderation_state'=>'clear','lifecycle_state'=>'active','created_at'=>gmdate('Y-m-d H:i:s')];}
    private static function submit():void{if(!isset($_POST['tnet_topic_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tnet_topic_nonce'])),'tnet_community_topic'))self::form(['Nonce verification failed.']);$community=sanitize_text_field(wp_unslash($_POST['community_id']??''));$submission_id=sanitize_text_field(wp_unslash($_POST['submission_id']??''))?:'web-'.wp_generate_uuid4();$title=sanitize_text_field(wp_unslash($_POST['title']??''));$body=sanitize_textarea_field(wp_unslash($_POST['body']??''));$mode=sanitize_key(wp_unslash($_POST['post_mode']??'discussion'));$urls=self::urls($body);$selected=esc_url_raw(wp_unslash($_POST['representative_url']??''));$representative=in_array($selected,$urls,true)?$selected:($urls[0]??'');$choice=sanitize_key(wp_unslash($_POST['preview_choice']??'keep'));$errors=[];if(!isset(self::COMMUNITIES[$community]))$errors[]='Choose a valid Community.';if($title==='')$errors[]='Enter a topic title.';if($body==='')$errors[]='Enter the topic body.';if(!isset(self::MODES[$mode]))$mode='discussion';$attachment=null;try{$attachment=self::upload();if($attachment&&!$attachment['alt_text'])$errors[]='Add alt text before publishing the image.';}catch(Throwable $e){$errors[]=$e->getMessage();}if($errors)self::form($errors,compact('community','submission_id','title','body','mode','representative','choice'));$preview=(new TNet_Community_Link_Attachment_Service())->prepare($representative,$choice);$draft=['submission_id'=>$submission_id,'community_id'=>$community,'author_id'=>'user:'.(int)get_current_user_id(),'post_type'=>'topic','title'=>$title,'body'=>$body,'parent_post_id'=>null,'visibility'=>'public','publication_mode'=>'post_first','moderation_input'=>'clear','compatibility_refs'=>['composer'=>['post_mode'=>$mode,'attachments'=>$attachment?[$attachment]:[],'links'=>array_map(static fn($u)=>['url'=>$u,'enrichment'=>'mocked'], $urls),'preview'=>$preview,'representative_url'=>$representative]],'audit_context'=>['source'=>'local-natural-composer']];$result=(new TNet_Community_Publisher_Application())->publish_and_persist($draft,self::COMMUNITIES,['actor_id'=>$draft['author_id']]);if(empty($result['accepted']))self::form(['The topic could not be published. Please try again.'],compact('community','submission_id','title','body','mode','representative','choice'));$path=str_replace('%3A',':',rawurlencode($result['post']['post_id']));wp_safe_redirect(home_url('/community/thread/'.$path.'/'));exit;}
    private static function form(array $errors,array $v=[]):void{$community=$v['community']??'community:local-demo';$sid=$v['submission_id']??'web-'.wp_generate_uuid4();$title=$v['title']??'';$body=$v['body']??'';$mode=$v['mode']??'discussion';$representative=$v['representative']??'';$choice=$v['choice']??'keep';status_header(200);nocache_headers();header('X-Robots-Tag: noindex,nofollow');echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Start a Discussion | Teachers.Net</title><style>body{font-family:system-ui,sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;line-height:1.5;color:#1d2327}main{border:1px solid #ccd0d4;border-radius:8px;padding:clamp(1rem,4vw,2rem)}label{display:block;font-weight:600;margin:.9rem 0 .35rem}input,select,textarea{box-sizing:border-box;width:100%;border:1px solid #8c8f94;border-radius:4px;padding:.65rem;font:inherit}textarea{min-height:12rem;resize:vertical}.section{border-top:1px solid #dcdcde;margin-top:1.25rem;padding-top:1rem}.hint,.status{color:#646970;font-size:.92rem}.staged{border:1px dashed #8c8f94;border-radius:6px;padding:1rem;margin-top:.75rem}.actions{display:flex;gap:1rem;align-items:center;margin-top:1.25rem}button{background:#135e96;color:#fff;border:0;border-radius:4px;padding:.7rem 1rem;font:inherit;font-weight:600;cursor:pointer}.secondary{background:#fff;color:#135e96;border:1px solid #135e96}.dropzone{border:2px dashed #8c8f94;border-radius:6px;padding:1rem;text-align:center}.dropzone.active{border-color:#135e96;background:#eef6fc}.errors{border-left:4px solid #b32d2e;background:#fcf0f1;padding:.75rem 1rem}.errors li+li{margin-top:.3rem}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #1d70b8;outline-offset:2px}@media(max-width:520px){.actions{align-items:stretch;flex-direction:column}}</style></head><body><main><p><a href="'.esc_url(home_url('/community/')).'">← Community</a></p><h1>Start a Discussion</h1>';if($errors)echo '<div class="errors" role="alert"><ul>'.implode('',array_map(static fn($e)=>'<li>'.esc_html($e).'</li>',$errors)).'</ul></div>';echo '<form method="post" enctype="multipart/form-data">'.wp_nonce_field('tnet_community_topic','tnet_topic_nonce',true,false).'<input type="hidden" name="submission_id" value="'.esc_attr($sid).'"/><section class="section"><label for="community_id">Community</label><select id="community_id" name="community_id"><option value="community:local-demo">Local Community Demo</option></select><label for="post_mode">Post type</label><select id="post_mode" name="post_mode">';foreach(self::MODES as $key=>$label)echo '<option value="'.esc_attr($key).'"'.selected($mode,$key,false).'>'.esc_html($label).'</option>';echo '</select></section><section class="section"><label for="title">Title</label><input id="title" name="title" value="'.esc_attr($title).'" required><label for="body">Body</label><textarea id="body" name="body" required aria-describedby="body-help">'.esc_textarea($body).'</textarea><p id="body-help" class="hint">Paste or type a link; the first eligible link gets a preview.</p><div id="staged-content" class="staged" aria-live="polite"><p class="status">No staged image. Add a photo or drop one here.</p><div id="dropzone" class="dropzone">Drop one JPEG, PNG, or WebP image here<br><label for="image_file">or choose a photo</label><input id="image_file" name="image_file" type="file" accept="image/jpeg,image/png,image/webp"></div><label for="attachment_alt">Image alt text</label><input id="attachment_alt" name="attachment_alt" type="text" aria-describedby="alt-help"><p id="alt-help" class="hint">Required when an image is staged.</p></div><label for="representative_url">Representative link</label><select id="representative_url" name="representative_url"><option value="">No link preview</option></select><label for="preview_choice">Preview</label><select id="preview_choice" name="preview_choice"><option value="keep">Keep preview</option><option value="remove">Dismiss preview</option><option value="raw">Keep link only</option></select><p id="link-status" class="status">Links remain in your post body.</p></section><div class="actions"><button type="submit">Publish Topic</button><a href="'.esc_url(home_url('/community/')).'">Cancel</a></div></form></main><script>(function(){const b=document.getElementById("body"),s=document.getElementById("representative_url"),f=document.getElementById("image_file"),d=document.getElementById("dropzone"),status=document.querySelector("#staged-content .status"),urls=()=>[...new Set((b.value.match(/https:\/\/[^\\s<>"\']+/gi)||[]).map(u=>u.replace(/[.,!?;:)]+$/,"")))];function links(){const current=s.value; s.innerHTML="<option value=\"\">No link preview</option>";urls().forEach(u=>s.insertAdjacentHTML("beforeend","<option value=\""+u.replace(/\"/g,"&quot;")+"\">"+u+"</option>"));s.value=urls().includes(current)?current:(urls()[0]||"");}function stage(file){if(!file)return;if(!["image/jpeg","image/png","image/webp"].includes(file.type)||file.size>10485760){status.textContent="Choose a JPEG, PNG, or WebP image up to 10 MB.";return;}status.textContent="Image staged: "+file.name;try{if(window._tnetObjectUrl)URL.revokeObjectURL(window._tnetObjectUrl);window._tnetObjectUrl=URL.createObjectURL(file);}catch(e){}}b.addEventListener("input",links);f.addEventListener("change",e=>stage(e.target.files[0]));["dragenter","dragover"].forEach(x=>d.addEventListener(x,e=>{e.preventDefault();d.classList.add("active");}));["dragleave","drop"].forEach(x=>d.addEventListener(x,e=>{e.preventDefault();d.classList.remove("active");}));d.addEventListener("drop",e=>stage(e.dataTransfer.files[0]));window.addEventListener("unload",()=>{if(window._tnetObjectUrl)URL.revokeObjectURL(window._tnetObjectUrl);});links();})();</script></body></html>';}
}
